const ticket = new Promise((resolve, reject) => reject(new Error("sold out")));

ticket
  .then(
    (seat) => console.log("seat " + seat),
    (error) => {
      console.log("first: " + error.message);
      return 0;
    }
  )
  .then(
    (seat) => {
      throw new Error("no seat " + seat);
    },
    (error) => console.log("second: " + error.message)
  )
  .catch((error) => console.log("third: " + error.message));
